import numpy as np
from scipy import stats
from sklearn.linear_model import LogisticRegression

MAX_DRIVERS = 4

def design(feats):
    # Filter out near-duplicates based on correlation
    corr_pairs = [(a, b) for a, b in [
        ('BQEB18', 'BWJE17'), ('BQEB18', 'SAH18P'), ('SAH18P', 'BWJE17'),
        ('ZZX13L', 'IVNZ2'), ('VJC10', 'IVNZ2'), ('BQEB18', 'ZIH17'),
        ('ZIH17', 'BWJE17'), ('SAH18P', 'ZIH17'), ('KTC18B', 'YBLV3'),
        ('BQEB18', 'IVNZ2'), ('ZZX13L', 'VJC10'), ('KTC18B', 'IVNZ2'),
        ('ZZX13L', 'KTC18B'), ('BQEB18', 'ZZX13L'), ('CMO19', 'IVNZ2'),
        ('BWJE17', 'IVNZ2'), ('KTC18B', 'VJC10'), ('BQEB18', 'VJC10'),
        ('VCRJ12', 'IVNZ2')
    ] if a in feats.ids and b in feats.ids]

    keep_ids = set(feats.ids)
    for a, b in corr_pairs:
        if a in keep_ids and b in keep_ids:
            keep_ids.remove(b)  # Remove one of the correlated pair

    # Select features with significant t-test or large effect size
    selected_features = []
    for i, fid in enumerate(feats.ids):
        if fid not in keep_ids:
            continue
        # Compute t-statistic manually
        if len(feats.y) > 0:
            group0 = feats.x[feats.y==0, feats.column(fid)]
            group1 = feats.x[feats.y==1, feats.column(fid)]
            if len(group0) > 0 and len(group1) > 0:
                t_stat = (group1.mean() - group0.mean()) / np.sqrt(
                    group1.var()/len(group1) + group0.var()/len(group0)
                )
                if abs(t_stat) > 2.0 or abs(group1.mean() - group0.mean()) > 0.2:
                    selected_features.append(fid)
        else:
            # Fallback for edge case
            if abs(feats.x[feats.y==1, feats.column(fid)].mean() - 
                   feats.x[feats.y==0, feats.column(fid)].mean()) > 0.2:
                selected_features.append(fid)

    # If no features meet criteria, return empty design
    if not selected_features:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Try to identify a causal driver using logistic regression
    try:
        X = feats.x[:, [feats.column(fid) for fid in selected_features]]
        y = feats.y

        # Fit logistic regression with L1 penalty to select important features
        clf = LogisticRegression(penalty='l1', solver='liblinear', random_state=42)
        clf.fit(X, y)

        # Get coefficients and select top features
        coefs = np.abs(clf.coef_[0])
        if len(coefs) > 0:
            top_indices = np.argsort(coefs)[::-1][:MAX_DRIVERS]
            top_features = [selected_features[i] for i in top_indices if i < len(selected_features) and coefs[i] > 0]
        else:
            top_features = []

        # If we have any features, use them as drivers
        if top_features:
            # Use all features with non-zero coefficients for regression
            columns = tuple(top_features)

            # For simplicity, we'll include interactions between top features
            products = []
            for i in range(len(top_features)):
                for j in range(i+1, len(top_features)):
                    products.append((top_features[i], top_features[j]))

            # Weighted score uses all selected features
            loadings = {}
            for i, fid in enumerate(selected_features):
                if i < len(clf.coef_[0]):
                    loadings[fid] = clf.coef_[0][i]

            return Design(drivers=tuple(top_features), columns=columns, products=tuple(products), loadings=loadings)

    except Exception:
        pass

    return Design(drivers=(), columns=(), products=(), loadings={})

